using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new Exception("Edit required");
            var old = EditorSceneManager.GetActiveScene();
            if (old.isDirty)
                throw new Exception("Unsaved changes; preserve them");
            string path = "Assets/Scenes/JourneyPresentation_v48_r103.unity";
            if (old.path != path)
                throw new Exception(old.path);
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            var sc = EditorSceneManager.OpenScene(path, OpenSceneMode.Single);
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            int count = 0;
            var bad = new StringBuilder();
            foreach (var c in s.GetComponentsInChildren<Component>(true))
            {
                if (!c)
                    continue;
                count++;
                var so = new SerializedObject(c);
                var p = so.GetIterator();
                while (p.NextVisible(true))
                    if (p.propertyType == SerializedPropertyType.ObjectReference && !p.objectReferenceEntityIdValue.Equals(System.Activator.CreateInstance(p.objectReferenceEntityIdValue.GetType())) && !p.objectReferenceValue)
                        bad.AppendLine(c.name + " " + c.GetType().Name + " " + p.propertyPath);
            }

            if (bad.Length > 0)
                throw new Exception(bad.ToString());
            string log = "Reopened " + sc.path + " dirty=" + sc.isDirty + " inspected components=" + count + " unresolved nonzero visible object refs=" + bad.Length + "\ninitial namespace=" + s.data.namespaceId + " initial records=" + s.data.evidence.Count + " finalized=" + s.data.finalized + "\nclip=" + s.repairEventMotion.name + " seconds=" + s.repairEventMotion.length + " actor=" + s.repairEventActor.name + " diagnostics=" + s.diagnostics;
            File.WriteAllText("Test/KetQua/investigation_r103/reopen-references.txt", log);
            r.Log(log);
        }
    }
}

